import os
import base64

_APP_B64 = ""

def generate_app(output_dir):
    _app = base64.b64decode(_APP_B64).decode("utf-8")
    dst = os.path.join(output_dir, "app.py")
    with open(dst, "w", encoding="utf-8") as f:
        f.write(_app)
    print(f"Flask API \u670d\u52a1\u5df2\u4fdd\u5b58: {dst}")
    return dst
